WITH recent_accounts AS (SELECT *, LENGTH(account_type) AS account_type_length FROM accounts WHERE customer_id IS NULL AND customer_id IS NULL AND status = 'OPEN'), account_type_summary AS (SELECT account_type, SUM(CASE WHEN status = 'OPEN' THEN account_type_length ELSE 0 END) AS open_account_type_length, SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END) AS open_count FROM recent_accounts GROUP BY account_type) SELECT account_type, open_account_type_length, open_count FROM account_type_summary WHERE open_count >= 38 ORDER BY account_type ASC
